import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Основы использования - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Выполнение чистых SQL-запросов","slug":"выполнение-чистых-sql-запросов","link":"#выполнение-чистых-sql-запросов","children":[{"level":3,"title":"Выборка записей","slug":"выборка-записеи","link":"#выборка-записеи","children":[]},{"level":3,"title":"Изменение записей","slug":"изменение-записеи","link":"#изменение-записеи","children":[]},{"level":3,"title":"Общие операторы","slug":"общие-операторы","link":"#общие-операторы","children":[]}]},{"level":2,"title":"Множественные подключения к базе данных","slug":"множественные-подключения-к-базе-данных","link":"#множественные-подключения-к-базе-данных","children":[]},{"level":2,"title":"Транзакции базы данных","slug":"транзакции-базы-данных","link":"#транзакции-базы-данных","children":[]},{"level":2,"title":"События базы данных","slug":"события-базы-данных","link":"#события-базы-данных","children":[{"level":3,"title":"Логирование запросов","slug":"логирование-запросов","link":"#логирование-запросов","children":[]}]}],"relativePath":"3.x/ru/extend/database/basics.md","filePath":"3.x/ru/extend/database/basics.md"}'),r={name:"3.x/ru/extend/database/basics.md"};function d(k,a,g,h,v,b){const p=e("pre-heading"),o=e("post-heading");return l(),i("div",null,[t(p),a[0]||(a[0]=s("h1",null,"Основы использования",-1)),t(o),a[1]||(a[1]=s("p",null,[n("Подключение к базам данных и выполнение запросов — это простой процесс, поддерживаемый использованием чистого SQL, "),s("a",{href:"./query.html"},"конструктора запросов"),n(" или "),s("a",{href:"./model.html"},"моделей Active Record"),n(". Управление таблицами базы данных и заполнение начальными данными осуществляется через процесс "),s("a",{href:"./structure.html"},"миграций и сидеров"),n(".")],-1)),a[2]||(a[2]=s("p",null,[n("Чистый SQL и использование конструктора запросов выполняются быстрее и должны использоваться для простых задач. Active Record — это подход, используемый популярным фреймворком Ruby On Rails. Он предоставляет простой интерфейс для выполнения повторяющихся задач, таких как создание, чтение, обновление и удаление записей базы данных. Вы можете узнать больше о "),s("a",{href:"http://en.wikipedia.org/wiki/Active_record_pattern",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("паттерне Active Record в Википедии"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(".")],-1)),a[3]||(a[3]=u(`<h2 id="выполнение-чистых-sql-запросов"><a href="#выполнение-чистых-sql-запросов" class="header-anchor">#</a> Выполнение чистых SQL-запросов</h2><p>После настройки подключения к базе данных вы можете выполнять запросы с помощью фасада <code>Db</code>. Фасад <code>Db</code> предоставляет методы для каждого типа запросов: <code>select</code>, <code>update</code>, <code>insert</code>, <code>delete</code> и <code>statement</code>.</p><h3 id="выборка-записеи"><a href="#выборка-записеи" class="header-anchor">#</a> Выборка записей</h3><p>Для выполнения базового запроса используйте метод <code>select</code> фасада <code>Db</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where active = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Первый аргумент, передаваемый методу <code>select</code> — это чистый SQL-запрос, а второй аргумент — привязка параметров, которые необходимо связать с запросом. Как правило, это значения ограничений оператора <code>where</code>. Привязка параметров обеспечивает защиту от SQL-инъекций.</p><p>Метод <code>select</code> всегда возвращает <code>array</code> результатов. Каждый результат в массиве будет объектом PHP <code>stdClass</code>, что позволяет получать доступ к значениям результатов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вместо использования <code>?</code> для представления привязки параметров вы можете выполнить запрос с использованием именованных привязок.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select * from users where id = :id&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если запрос к базе данных может вернуть единственное значение, его можно получить с помощью метода <code>scalar</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">scalar</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;select count(*) as count from menu_items&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="изменение-записеи"><a href="#изменение-записеи" class="header-anchor">#</a> Изменение записей</h3><p>Для выполнения оператора <code>insert</code> вы можете использовать метод <code>insert</code> фасада <code>Db</code>. Как и <code>select</code>, этот метод принимает чистый SQL-запрос в качестве первого аргумента и привязки в качестве второго аргумента.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;insert into users (id, name) values (?, ?)&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>update</code> следует использовать для обновления существующих записей в базе данных. Количество затронутых строк будет возвращено методом:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$affected</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;update users set votes = 100 where name = ?&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;John&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>delete</code> следует использовать для удаления записей из базы данных. Как и <code>update</code>, количество удалённых строк будет возвращено:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deleted</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;delete from users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="общие-операторы"><a href="#общие-операторы" class="header-anchor">#</a> Общие операторы</h3><p>Некоторые операторы базы данных не должны возвращать значение. Для таких типов операций вы можете использовать метод <code>statement</code> фасада <code>Db</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">statement</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;drop table users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="множественные-подключения-к-базе-данных"><a href="#множественные-подключения-к-базе-данных" class="header-anchor">#</a> Множественные подключения к базе данных</h2><p>При <a href="./../../setup/database-config.html">использовании нескольких подключений</a> вы можете получить доступ к каждому подключению через метод <code>connection</code> фасада <code>Db</code>. Имя <code>name</code>, передаваемое методу <code>connection</code>, должно соответствовать одному из подключений, перечисленных в вашем файле конфигурации <code>config/database.php</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">select</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете получить доступ к базовому экземпляру PDO с помощью метода <code>getPdo</code> на экземпляре подключения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$pdo</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">getPdo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="транзакции-базы-данных"><a href="#транзакции-базы-данных" class="header-anchor">#</a> Транзакции базы данных</h2><p>Для выполнения набора операций внутри транзакции базы данных вы можете использовать метод <code>transaction</code> фасада <code>Db</code>. Если внутри <code>Closure</code> транзакции будет выброшено исключение, транзакция автоматически откатится. Если <code>Closure</code> выполнится успешно, транзакция автоматически подтвердится. Вам не нужно беспокоиться о ручном откате или подтверждении при использовании метода <code>transaction</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">transaction</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите начать транзакцию вручную и иметь полный контроль над откатами и подтверждениями, вы можете использовать метод <code>beginTransaction</code> фасада <code>Db</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">beginTransaction</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете откатить транзакцию с помощью метода <code>rollBack</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">rollBack</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Наконец, вы можете подтвердить транзакцию с помощью метода <code>commit</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">commit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Использование методов транзакций фасада <code>Db</code> также управляет транзакциями для <a href="./query.html">конструктора запросов</a> и <a href="./model.html">запросов моделей</a>.</p></div><h2 id="события-базы-данных"><a href="#события-базы-данных" class="header-anchor">#</a> События базы данных</h2><p>Если вы хотите получать каждый SQL-запрос, выполняемый вашим приложением, вы можете использовать метод <code>listen</code>. Этот метод полезен для логирования запросов или отладки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$sql</span><span class="token punctuation">,</span> <span class="token variable">$bindings</span><span class="token punctuation">,</span> <span class="token variable">$time</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете зарегистрировать свой слушатель запросов в методе <code>boot</code> <a href="./../extending.html">файла регистрации плагина</a>. Кроме того, плагины могут предоставлять файл с именем <strong>init.php</strong> в директории плагина, который можно использовать для размещения этой логики.</p><h3 id="логирование-запросов"><a href="#логирование-запросов" class="header-anchor">#</a> Логирование запросов</h3><p>При включении логирования запросов в памяти ведётся журнал всех запросов, выполненных для текущего запроса. Вызовите метод <code>enableQueryLog</code> для включения этой функции.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">enableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для получения массива выполненных запросов вы можете использовать метод <code>getQueryLog</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$queries</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">getQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Однако в некоторых случаях, например при вставке большого количества строк, это может привести к чрезмерному использованию памяти приложением. Для отключения журнала вы можете использовать метод <code>disableQueryLog</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">disableQueryLog</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Для более быстрой отладки может быть полезнее вызвать <a href="./../services/log.html">вспомогательную функцию</a> <code>trace_sql</code>.</p></div>`,49))])}const x=c(r,[["render",d]]);export{f as __pageData,x as default};
